7	/**
8	 * Normalizes the owner's telephone on create into E.164 form, mutating the validated request in
9	 * place so later steps store and return the E.164 value. Spaces, dashes and brackets are stripped.
10	 * A leading '+' and its country code are kept as given; otherwise country code '+61' is assumed and
11	 * a single leading '0' is dropped from the national digits (so {@code 0412 345 678} becomes
12	 * {@code +61412345678}). The result must carry 8 to 15 digits after the '+'; anything that cannot
13	 * form valid E.164 is rejected 400 via {@link InvalidTelephoneException}.
14	 */
15	public class NormalizeOwnerTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
18	        request.setTelephone(toE164(request.getTelephone()));
19	    }
20	
21	    /**
22	     * The single source of truth for what "same telephone" means: converts a raw telephone into its
23	     * E.164 form. Spaces, dashes and brackets are removed; a leading '+' and country code are kept,
24	     * otherwise '+61' is assumed and a single leading '0' is dropped from the national digits. The
25	     * digits after the '+' must number 8 to 15, and no other characters may remain. Shared with
26	     * {@link CheckOwnerTelephoneUnique} so the request side and stored owners are normalized
27	     * identically.
28	     *
29	     * @throws InvalidTelephoneException if the value cannot form valid E.164.
30	     */
31	    static String toE164(String telephone) throws InvalidTelephoneException {
32	        if (telephone == null) {
33	            throw invalid();
34	        }
35	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
36	        String digits;
37	        if (cleaned.startsWith("+")) {
38	            digits = cleaned.substring(1);
39	        }
40	        else {
41	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
42	            digits = "61" + national;
43	        }
44	        if (!digits.matches("\\d{8,15}")) {
45	            throw invalid();
46	        }
47	        return "+" + digits;
48	    }
49	
50	    private static InvalidTelephoneException invalid() {
51	        return new InvalidTelephoneException(
52	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
53	    }
54	}
