15	/**
16	 * Assigns a shared, stable {@code householdId} when the request opts in with
17	 * {@code sharesHousehold=true} and an existing owner shares the same household. What counts
18	 * as the same household — same lastName AND address, compared on their normalized forms — is
19	 * single-sourced in
20	 * {@link CheckOwnerHouseholdUnique#sameHousehold}, so the 409 bypass and this id assignment
21	 * agree by construction. The identifier is derived deterministically from the
22	 * normalized lastName and address, so every owner in one household receives the same value
23	 * regardless of creation order. Both the joining owner and any matching existing owner that
24	 * still lacks the id are stamped with it, so the household is linked on both sides. Runs
25	 * after {@link BuildOwner} has created the entity (and {@link CheckOwnerHouseholdUnique} has
26	 * allowed the collision) and before {@link SaveOwner} persists it. When the request does not
27	 * opt in, or opts in but no existing owner shares the household, the id is left unset.
28	 */
29	public class AssignOwnerHousehold {
30	
31	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
32	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
33	            return;
34	        }
35	        List<Owner> matches = new ArrayList<>();
36	        String shared = null;
37	        for (Owner existing : ownerRepository.findAll()) {
38	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
39	                continue;
40	            }
41	            if (CheckOwnerHouseholdUnique.sameHousehold(owner.getLastName(), owner.getAddress(),
42	                    existing.getLastName(), existing.getAddress())) {
43	                matches.add(existing);
44	                if (shared == null && existing.getHouseholdId() != null) {
45	                    shared = existing.getHouseholdId();
46	                }
47	            }
48	        }
49	        if (matches.isEmpty()) {
50	            return;
51	        }
52	        if (shared == null) {
53	            shared = deriveHouseholdId(CheckOwnerHouseholdUnique.normalize(owner.getLastName()),
54	                    NormalizeOwnerAddress.normalize(owner.getAddress()));
55	        }
56	        owner.setHouseholdId(shared);
57	        for (Owner existing : matches) {
58	            if (existing.getHouseholdId() == null) {
59	                existing.setHouseholdId(shared);
60	                ownerRepository.save(existing);
61	            }
62	        }
63	    }
64	
65	    /**
66	     * Derives the stable household identifier {@code HH-<12 upper hex>} from the SHA-256 of the
67	     * normalized {@code lastName|address}, so two owners in the same household compute the same id.
68	     */
69	    private static String deriveHouseholdId(String lastName, String address) {
70	        try {
71	            byte[] digest = MessageDigest.getInstance("SHA-256")
72	                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
73	            StringBuilder sb = new StringBuilder(12);
74	            for (int i = 0; i < 6; i++) {
75	                sb.append(String.format("%02X", digest[i]));
76	            }
77	            return "HH-" + sb.toString().toUpperCase(Locale.ROOT);
78	        }
79	        catch (NoSuchAlgorithmException ex) {
80	            throw new IllegalStateException("SHA-256 not available", ex);
81	        }
82	    }
83	}
